package com.daniil.wristlens.wear;
import android.content.*;import android.database.Cursor;import android.net.Uri;import android.os.ParcelFileDescriptor;import android.provider.MediaStore;import java.io.IOException;
/** Shared commit journal prevents duplicate originals and recovers interrupted publication. */
final class OriginalCopies {
 private static final Object LOCK=new Object();private static final java.util.Set<String> live=new java.util.HashSet<>();
 static void begin(Context c,Uri uri)throws IOException{synchronized(LOCK){live.add(uri.toString());if(!c.getSharedPreferences("pending_copies",0).edit().putBoolean(uri.toString(),true).commit()){live.remove(uri.toString());throw new IOException("Cannot save pending copy");}}}
 static void end(Context c,Uri uri){synchronized(LOCK){live.remove(uri.toString());c.getSharedPreferences("pending_copies",0).edit().remove(uri.toString()).apply();}}
 static void recover(Context c){synchronized(LOCK){SharedPreferences p=c.getSharedPreferences("pending_copies",0);for(String value:p.getAll().keySet()){if(live.contains(value))continue;Uri uri=Uri.parse(value);try(Cursor row=c.getContentResolver().query(uri,new String[]{MediaStore.MediaColumns.IS_PENDING},null,null,null)){if(row!=null&&row.moveToFirst()&&row.getInt(0)==1)c.getContentResolver().delete(uri,null,null);}catch(Exception ignored){}p.edit().remove(value).apply();}}}

 static Uri find(Context c,String id){synchronized(LOCK){SharedPreferences p=c.getSharedPreferences("copies",0);String value=p.getString(id,"");if(value.isEmpty())return null;Uri uri=Uri.parse(value);try(Cursor row=c.getContentResolver().query(uri,new String[]{MediaStore.MediaColumns.IS_PENDING},null,null,null)){if(row!=null&&row.moveToFirst()&&row.getInt(0)==0)try(ParcelFileDescriptor fd=c.getContentResolver().openFileDescriptor(uri,"r")){if(fd!=null&&fd.getStatSize()>0)return uri;}if(row!=null&&row.getCount()>0)c.getContentResolver().delete(uri,null,null);}catch(Exception ignored){}p.edit().remove(id).apply();return null;}}
 static Uri commit(Context c,String id,Uri incoming)throws IOException{synchronized(LOCK){Uri old=find(c,id);if(old!=null){c.getContentResolver().delete(incoming,null,null);return old;}if(!c.getSharedPreferences("copies",0).edit().putString(id,incoming.toString()).commit())throw new IOException(com.daniil.wristlens.shared.Strings.tr(com.daniil.wristlens.shared.R.string.wl_extra_13));ContentValues v=new ContentValues();v.put(MediaStore.MediaColumns.IS_PENDING,0);if(c.getContentResolver().update(incoming,v,null,null)!=1)throw new IOException(com.daniil.wristlens.shared.Strings.tr(com.daniil.wristlens.shared.R.string.wl_extra_14));return incoming;}}
}
